package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ConsultaMedicaService {private final ConsultaMedicaRepository repo;private final CitaRepository citas;public ConsultaMedicaService(ConsultaMedicaRepository r,CitaRepository c){repo=r;citas=c;}@Transactional public ConsultaMedica iniciar(UUID empresa,UUID citaId,String historia,String examen){Cita cita=citas.findById(citaId).filter(c->empresa.equals(c.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("Cita no encontrada para esta empresa."));if(!"EN_CONSULTA".equals(cita.getEstado()))throw new IllegalArgumentException("La cita debe estar en consulta.");ConsultaMedica x=new ConsultaMedica();x.setEmpresaId(empresa);x.setCitaId(citaId);x.setPacienteId(cita.getPaciente().getId());x.setMedicoId(cita.getMedico().getId());x.setMotivo(cita.getMotivo());x.setHistoriaActual(historia);x.setExamenObservaciones(examen);return repo.save(x);}@Transactional public void finalizar(UUID empresa,UUID citaId){Cita c=citas.findById(citaId).filter(x->empresa.equals(x.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("Cita no encontrada para esta empresa."));if(!"EN_CONSULTA".equals(c.getEstado()))throw new IllegalArgumentException("La cita no está en consulta.");c.setEstado("ATENDIDA");citas.save(c);}}
